  'help.describePlaceholder': 'Napiš, co se stalo, co nejpodrobněji...',
  'help.send': 'Odeslat tiket',
  'help.ticketSent': 'Tiket odeslán!',
  'help.ticketSentDesc': 'Dostali jsme tvou žádost. Náš tým ti odpoví e-mailem do 24 hodin.',
  'help.close': 'Zavřít',
  'help.ticketError': 'Chyba při odesílání tiketu. Zkus to znovu.',
  'help.type.cant_login': 'Nemůžu se přihlásit',
  'help.type.email_issue': 'Problém s e-mailem',
  'help.type.security': 'Bezpečnost',
  'help.type.other': 'Jiné',
  'help.faq.cantLogin.q': 'Nemůžu se dostat ke svému účtu',
  'help.faq.cantLogin.a': 'Zkontroluj, jestli používáš správný e-mail a heslo. Pokud jsi zapomněl heslo, klikni na "Zapomněl jsi heslo?" na přihlašovací obrazovce. Pokud problém přetrvává, vytvoř tiket na podporu.',
  'help.faq.notReceiving.q': 'Nedostávám e-maily',
  'help.faq.notReceiving.a': 'Nejprve zkontroluj složku Spam. Ujisti se, že máš dostatek místa. Pokud problém pokračuje, ověř, že odesílatel má správnou adresu a vytvoř tiket.',
  'help.faq.cantSend.q': 'Nemůžu posílat e-maily',
  'help.faq.cantSend.a': 'Zkontroluj své internetové připojení a zda je adresa příjemce správná. Zkontroluj, že přílohy nepřesahují 25 MB. Zkus to znovu za pár minut.',
  'help.faq.forgotPassword.q': 'Zapomněl jsem své heslo',
  'help.faq.forgotPassword.a': 'Na přihlašovací obrazovce klikni na "Zapomněl jsi heslo?" a postupuj podle pokynů pro resetování hesla přes e-mail.',
  'help.faq.accountSecurity.q': 'Myslím, že můj účet byl kompromitován',
  'help.faq.accountSecurity.a': 'Okamžitě změň své heslo. Zkontroluj složku Odeslané zprávy na zprávy, které jsi neodeslal. Aktivuj dvoufázové ověření v Nastavení > Bezpečnost. Pokud je to nutné, vytvoř urgentní tiket.',
  'help.faq.appAccess.q': 'Jak se dostanu k aplikaci na mobilu?',
  'help.faq.appAccess.a': 'Můžeš přistupovat k Chatyy přes prohlížeč na chatyy.com.br, nebo si stáhnout naši aplikaci z obchodu s aplikacemi tvého zařízení.',
  'privacy.title': 'Zásady ochrany soukromí',
  'privacy.subtitle': 'Jak chráníme a zpracováváme tvá data',
  'privacy.lastUpdated': 'Poslední aktualizace: Březen 2026',
  'privacy.dataCollection.title': 'Sběr dat',
  'privacy.dataCollection.body': 'Shromažďujeme pouze nezbytné informace pro e-mailovou službu: tvé jméno, e-mailovou adresu a obsah odeslaných a přijatých zpráv. Neprodáváme ani nesdílíme tvá osobní data s třetími stranami pro marketingové účely.',
  'privacy.dataUsage.title': 'Jak používáme tvá data',
  'privacy.dataUsage.body': 'Tvoje data jsou používána výhradně k provozu a zlepšení e-mailové služby, včetně doručování zpráv, filtrování spamu, funkcí AI (s tvým souhlasem) a bezpečnosti účtu.',
  'privacy.dataSecurity.title': 'Bezpečnost dat',
  'privacy.dataSecurity.body': 'Používáme standardní průmyslovou šifrování (TLS/SSL) pro všechna data v přenosu a v klidu. Relace jsou chráněny šifrovanými tokeny a ochranou CSRF. Pravidelně auditujeme naše bezpečnostní praktiky.',
  'privacy.cookies.title': 'Cookies a místní úložiště',
  'privacy.cookies.body': 'Používáme nezbytné cookies a místní úložiště k udržení tvé relace, zapamatování tvých preferencí (téma, jazyk) a zajištění plynulé zkušenosti. Nepoužíváme cookies třetích stran pro sledování.',
  'privacy.thirdParties.title': 'Služby třetích stran',
  'privacy.thirdParties.body': 'Můžeme používat služby třetích stran pro specifické funkce jako AI (Anthropic Claude) a push notifikace. Tyto služby dodržují své vlastní zásady ochrany soukromí a zpracovávají pouze minimální nezbytná data.',
  'privacy.rights.title': 'Tvoje práva',
  'privacy.rights.body': 'Máš právo kdykoliv přistupovat, opravovat, exportovat nebo mazat svá osobní data. Můžeš spravovat svá data v Nastavení nebo kontaktováním naší podpory.',
  'privacy.contact.title': 'Kontaktuj nás',
  'privacy.contact.body': 'Pro otázky ohledně ochrany soukromí nebo žádosti o data nás kontaktuj na privacy@chatyy.com.br. Odpovíme do 30 dnů.',
  'terms.title': 'Podmínky služby',
  'terms.subtitle': 'Pokyny pro používání Chatyy',
  'terms.lastUpdated': 'Poslední aktualizace: Březen 2026',
  'terms.acceptance.title': 'Přijetí podmínek',
  'terms.acceptance.body': 'Při přístupu nebo používání Chatyy souhlasíš s těmito Podmínkami služby. Pokud nesouhlasíš s jakoukoli částí těchto podmínek, nepoužívej službu.',
  'terms.services.title': 'Popis služeb',
  'terms.services.body': 'Chatyy poskytuje služby komunikace prostřednictvím e-mailu, včetně odesílání, přijímání a správy e-mailů, stejně jako funkce AI, integraci s kalendářem a videokonference.',
  'terms.accounts.title': 'Uživatelské účty',
  'terms.accounts.body': 'Ty jsi odpovědný za udržení bezpečnosti svých přihlašovacích údajů. Nesdílej své heslo ani nedovoluj neoprávněný přístup k tvému účtu. Musíš mít alespoň 13 let, abys mohl tuto službu používat.',
  'terms.conduct.title': 'Přijatelný způsob používání',
  'terms.conduct.body': 'Souhlasíš s tím, že nebudeš službu používat k odesílání spamu, malwaru, phishingu nebo jakéhokoli nezákonného obsahu. Nepokoušej se přistupovat k účtům jiných uživatelů nebo narušovat infrastrukturu služby.',
  'terms.content.title': 'Vlastnictví obsahu',
  'terms.content.body': 'Zůstáváš vlastníkem veškerého obsahu, který vytváříš a odesíláš prostřednictvím služby. Nežádáme o vlastnictví tvých e-mailů nebo příloh. Můžeme zpracovávat obsah podle potřeby k poskytování služby.',
  'terms.limitation.title': 'Omezení odpovědnosti',
  'terms.limitation.body': 'Chatyy je poskytováno "tak, jak je". Usilujeme o 99,9% dostupnost, ale nezaručujeme nepřetržitou službu. Nejsme odpovědní za nepřímé, náhodné nebo následné škody vyplývající z používání služby.',
  'terms.termination.title': 'Ukončení účtu',
  'terms.termination.body': 'Můžeme pozastavit nebo ukončit účty, které porušují tyto podmínky. Svůj účet můžeš kdykoliv smazat v Nastavení. Po ukončení budou tvá data smazána do 30 dnů.',
  'terms.changes.title': 'Změny podmínek',
  'terms.changes.body': 'Můžeme tyto podmínky pravidelně aktualizovat. O významných změnách tě budeme informovat e-mailem nebo notifikací v aplikaci. Pokračující používání po změnách představuje souhlas s aktualizovanými podmínkami.',
