  'plans.storageWarningUpgrade': 'Udělej upgrade na Chatyy One a získej 200 GB!',
  'plans.faqWhatIsPlus': 'Co je Chatyy One?',
  'plans.faqWhatIsPlusAnswer': 'Je to prémiový plán Chatyy, který chrání všechny tvé konverzace, fotky a videa. S Chatyy One, i když něco omylem smažeš, můžeš to obnovit až do 30 dnů. Navíc získáš 200GB úložiště, One AI jako osobního asistenta a můžeš posílat soubory až do 100MB.',
  'plans.faqCancelAnswer': 'Tvůj plán zůstává aktivní do konce zaplaceného období. Poté se vrátíš na bezplatný plán. Tvé fotky a videa, které překročí 15GB, budou uchovány ještě 30 dní, abys je mohl stáhnout.',
  'plans.faqHowFamily': 'Jak funguje Pro plán?',
  'plans.faqHowFamilyAnswer': 'Můžeš přidat až 4 členy rodiny. Všichni sdílejí 500GB úložiště a získávají všechny výhody Chatyy One. Každý má své soukromé místo — nikdo nevidí soubory ostatních.',
  'plans.faqChangePlanAnswer': 'Ano! Pokud uděláš upgrade z Plus na Pro, bude ti účtován pouze poměrný rozdíl. Pokud uděláš downgrade, aktuální plán zůstává až do konce období.',
  'plans.faqCardDeclined': 'Moje karta byla zamítnuta, co mám dělat?',
  'plans.faqCardDeclinedAnswer': 'Máš 7 dní na aktualizaci své karty. Během této doby všechny tvé výhody zůstávají aktivní. Po 7 dnech se plán vrátí na bezplatný.',
  'plans.faqDataSafe': 'Jsou moje data v bezpečí?',
  'plans.faqDataSafeAnswer': 'Ano! Tvé platební údaje jsou zpracovávány s šifrováním end-to-end. Neuchováváme číslo tvé karty — pouze poslední 4 číslice pro tvou referenci.',
